          'そのためにも、大人自身の余裕が大切な資源になります。睡眠を確保する、頼れる人に頼る、深呼吸や数秒の間を置くなど、自分なりの落ち着き方を持っておくこと。大人のセルフケアは、ぜいたくではなく共調整の土台です。',
