          '過去の出来事を思い返す、自分について考える、人の気持ちを想像する、未来を思い描く——といった「内側に向かう思考」に関わります。',
          '「デフォルト（初期設定）」という名前は、何かの課題に取り組むと活動が下がり、課題が終わると戻ってくる、いわば脳の基本モードであることに由来します。脳は休んでいるように見える間も、多くのエネルギーを使って働き続けていることが知られています。',
