          '具体的には、子どもと遊んでいる途中で通知を確かめる、食事中にメッセージを返す、話しかけられてもスマホから目を離さない——といった、日常の小さな中断の積み重ねを指します。調査研究では、多くの家庭でこうした中断が日常的に起きていることが報告されています。',
