          '共感の芽は、生まれて間もない頃から見られます。赤ちゃんが他の赤ちゃんの泣き声につられて泣く「情動伝染」はその原型と考えられており、成長とともに、自分と相手を区別したうえで相手の立場を想像する認知的な側面が育っていきます。2つの側面は別々に働くこともあり、たとえば相手の気持ちを頭では理解できても心が動かない、逆に相手の涙に自分もつらくなるのに理由がうまく分からない、ということも起こります。',
