          '「EQが高ければ必ず成功する」といった強い主張には、研究の裏づけが十分とは言えません。一方で、感情を理解し扱うスキルを学校の授業で育てるSEL（社会情動的学習）については、子どもの社会性や学業への良い影響を示す研究の蓄積があります。派手な宣伝文句と、地道な研究知見を分けて見ることが大切です。',
